    page(22);pdf.setFillColor(...navy);pdf.rect(margin,y,180,15,"F");pdf.setTextColor(255,255,255);pdf.setFont("helvetica","bold");pdf.setFontSize(10);pdf.text(settlement.pdfHeading,margin+5,y+6);pdf.setFontSize(13);pdf.text(money(settlement.displayAmount,currency),190,y+10,{align:"right"});y+=22;
